import type { AnchorHTMLAttributes, HTMLAttributes } from "react";

export function Pagination({ className = "", ...props }: HTMLAttributes<HTMLElement>) { return <nav aria-label="Pagination" className={`co-flex co-justify-center ${className}`.trim()} {...props} />; }
export function PaginationContent({ className = "", ...props }: HTMLAttributes<HTMLUListElement>) { return <ul className={`co-flex co-items-center co-gap-1 ${className}`.trim()} {...props} />; }
export function PaginationLink({ current = false, className = "", ...props }: AnchorHTMLAttributes<HTMLAnchorElement> & { current?: boolean }) { return <a aria-current={current ? "page" : undefined} className={`co-grid co-size-9 co-place-items-center co-rounded-md co-text-sm hover:co-bg-black/5 focus-visible:co-ring-2 ${current ? "co-bg-black co-text-white" : ""} ${className}`.trim()} {...props} />; }
export function PaginationEllipsis() { return <span aria-hidden="true" className="co-grid co-size-9 co-place-items-center">…</span>; }
